def to_text(v):
    if v is None:
        return ""
    s = str(v)
    return "" if s.lower() in ("nan", "nat", "none", "null") else s.strip()


def to_float(v, default=0.0):
    try:
        if v is None or v == "":
            return default
        n = float(v)
        return n if math.isfinite(n) else default
    except Exception:
        return default


def to_bool(v, default=False):
    if isinstance(v, bool):
        return v
    s = to_text(v).lower()
    if not s:
        return default
    return s in {"1", "true", "yes", "y", "on"}


def normalize_timestamp(value):
    if value is None or value == "":
        return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")
    text = str(value).strip()
    if re.match(r"^\d{8}-\d{2}:\d{2}:\d{2}$", text):
        return f"{text[0:4]}-{text[4:6]}-{text[6:8]} {text[9:17]}"
    if "T" in text:
        text = text.replace("T", " ")
    if text.endswith("Z"):
        text = text[:-1].strip()
    if re.match(r"^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}", text):
        return text
    return datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M:%S")


def parse_paths(v):
    if v is None:
        return []
    if isinstance(v, (list, tuple, set)):
        return [to_text(x) for x in v if to_text(x)]
    s = to_text(v)
    if not s:
        return []
    if s.startswith("[") and s.endswith("]"):
        try:
            arr = json.loads(s)
            if isinstance(arr, list):
                return [to_text(x) for x in arr if to_text(x)]
        except Exception:
            pass
    if "," in s or ";" in s:
        return [
            to_text(x).strip().strip('"').strip("'")
            for x in re.split(r"[;,]", s.strip().strip("[]"))
            if to_text(x).strip().strip('"').strip("'")
        ]
    return [s]


def dedupe(values):
    out = []
    seen = set()
    for value in values:
        text = to_text(value)
        if not text:
            continue
        key = text.lower()
        if key in seen:
            continue
        seen.add(key)
        out.append(text)
    return out


def path_aliases(path_text):
    p = to_text(path_text).replace("\\", "/")
    if not p:
        return []
    out = [p]
    if p.startswith("/files/"):
        out.append("/local-files/" + p[len("/files/"):])
    elif p.startswith("/local-files/"):
        out.append("/files/" + p[len("/local-files/"):])
    return dedupe(out)


def resolve_existing_path(path_text):
    aliases = path_aliases(path_text)
    for p in aliases:
        try:
            if os.path.exists(p):
                return p
        except Exception:
            pass
    return aliases[0] if aliases else ""


def resolve_writable_path(path_text):
    aliases = path_aliases(path_text)
    for p in aliases:
        try:
            if os.path.exists(p):
                return p
        except Exception:
            pass
    for p in aliases:
        try:
            if os.path.isdir(os.path.dirname(p)):
                return p
        except Exception:
            pass
    return aliases[0] if aliases else ""


@contextmanager
def db_con(path, read_only=False, retries=7, base_delay=0.25):
    con = None
    for attempt in range(retries):
        try:
            con = duckdb.connect(path, read_only=read_only)
            break
        except Exception as exc:
            msg = str(exc).lower()
            if ("lock" in msg or "busy" in msg) and attempt < retries - 1:
                time.sleep(base_delay * (2 ** attempt))
                continue
            raise
    try:
        yield con
    finally:
        if con is not None:
            if not read_only:
                try:
                    con.execute("CHECKPOINT")
                except Exception:
                    pass
            try:
                con.close()
            except Exception:
                pass
        gc.collect()


def split_sql(text):
    buff = []
    out = []
    sq = False
    dq = False
    for ch in text:
        if ch == "'" and not dq:
            sq = not sq
        elif ch == '"' and not sq:
            dq = not dq
        if ch == ";" and not sq and not dq:
            stmt = "".join(buff).strip()
            if stmt:
                out.append(stmt)
            buff = []
        else:
            buff.append(ch)
    stmt = "".join(buff).strip()
    if stmt:
        out.append(stmt)
    return out


def init_schema_if_available(con, schema_path):
    path = resolve_existing_path(schema_path)
    if not path:
        return False
    p = Path(path)
    if not p.is_file():
        return False
    for stmt in split_sql(p.read_text(encoding="utf-8")):
        con.execute(stmt)
    return True


def table_exists(con, table_name, schema="core"):
    row = con.execute(
        """
        SELECT COUNT(*)
        FROM information_schema.tables
        WHERE table_schema = ? AND table_name = ?
        """,
        [schema, table_name],
    ).fetchone()
    return bool(row and int(row[0] or 0) > 0)


def fetch_price_from_yfinance(base_url, pair, cfg):
    symbol = f"{pair}=X"
    params = {
        "symbol": symbol,
        "interval": to_text(cfg.get("interval")) or "1h",
        "lookback_days": int(to_float(cfg.get("lookback_days"), 5)),
        "max_bars": int(to_float(cfg.get("max_bars"), 10)),
        "min_bars": int(to_float(cfg.get("min_bars"), 1)),
        "allow_stale": "true" if to_bool(cfg.get("allow_stale"), True) else "false",
    }
    url = f"{base_url.rstrip('/')}/history?{urlencode(params)}"
    req = Request(url, headers={"Accept": "application/json"})
    timeout = max(1, int(to_float(cfg.get("request_timeout_seconds"), DEFAULT_REQUEST_TIMEOUT_SECONDS)))
    with urlopen(req, timeout=timeout) as resp:
        payload = json.loads(resp.read().decode("utf-8"))

    if payload.get("ok") is False:
        raise RuntimeError(payload.get("error") or "yfinance ok=false")
    if isinstance(payload.get("last"), dict):
        px = to_float(payload["last"].get("c"), 0)
        if px > 0:
            return {
                "pair": pair,
                "price": px,
                "as_of": payload["last"].get("t"),
                "source": payload.get("source") or "yfinance_api",
                "stale": bool(payload.get("stale")),
            }
    bars = payload.get("bars") if isinstance(payload.get("bars"), list) else []
    if bars:
        last = bars[-1]
        px = to_float(last.get("c"), 0)
        if px > 0:
            return {
                "pair": pair,
                "price": px,
                "as_of": last.get("t"),
                "source": payload.get("source") or "yfinance_api",
                "stale": bool(payload.get("stale")),
            }
    raise RuntimeError("No last price in yfinance payload")


def fetch_broker_json(base_url, path, timeout=12):
    req = Request(f"{base_url.rstrip('/')}{path}", headers={"Accept": "application/json"})
    with urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


def post_broker_json(base_url, path, payload=None, timeout=12):
    req = Request(
        f"{base_url.rstrip('/')}{path}",
        data=json.dumps(payload or {}).encode("utf-8"),
        headers={"Accept": "application/json", "Content-Type": "application/json"},
        method="POST",
    )
    with urlopen(req, timeout=timeout) as resp:
        return json.loads(resp.read().decode("utf-8"))


